import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/commands.md","filePath":"guide/commands.md"}'),r={name:"guide/commands.md"};function s(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>Configure AsyncUp by @mentioning it in the space where reports post. When a space has <strong>several standups</strong>, prefix commands with the standup id, e.g. <code>@AsyncUp #2 time 09:30</code> — <code>status</code> lists all standups with their ids.</p><p><code>help</code> shows the essentials; <code>help all</code> lists every command.</p><h2 id="configuration-admins-only" tabindex="-1">Configuration (admins only) <a class="header-anchor" href="#configuration-admins-only" aria-label="Permalink to &quot;Configuration (admins only)&quot;">​</a></h2><p>The person who runs <code>setup</code> becomes the standup&#39;s first admin (<code>setup</code> itself is open to everyone in the space — there is nobody to gate it before the first standup exists). Only admins can change configuration; <code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, <code>poll</code>, <code>polls</code>, <code>export</code> and <code>help</code> are open to everyone in the space. <code>status</code> without a <code>#id</code> prefix reports every standup in the space.</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>setup [name]</code></td><td>Create a standup reporting to this space (creator becomes admin; duplicate names are refused)</td></tr><tr><td><code>run now</code></td><td>Open today&#39;s run immediately and prompt everyone — see the whole flow without waiting for the schedule</td></tr><tr><td><code>archive</code></td><td>Retire the standup: prompts and reports stop, history stays</td></tr><tr><td><code>add @user…</code></td><td>Add participants (mandatory by default)</td></tr><tr><td><code>remove @user…</code></td><td>Remove participants</td></tr><tr><td><code>mandatory @user…</code> / <code>optional @user…</code></td><td>Count toward the wrap-up report, or not</td></tr><tr><td><code>vacation @user…</code> / <code>back @user…</code></td><td>Mark people away — no prompts, not counted as missing</td></tr><tr><td><code>admin @user…</code> / <code>unadmin @user…</code></td><td>Manage who can change configuration</td></tr><tr><td><code>time HH:MM</code></td><td>Prompt time — interpreted in each participant&#39;s own timezone (participants set theirs by DMing <code>timezone &lt;IANA&gt;</code>; default is the standup timezone)</td></tr><tr><td><code>deadline HH:MM</code></td><td>When the run closes and the wrap-up posts — standup timezone</td></tr><tr><td><code>remind &lt;minutes&gt;</code></td><td>Nudge non-submitters this many minutes before the deadline (<code>0</code> disables)</td></tr><tr><td><code>timezone &lt;IANA&gt;</code></td><td>Standup timezone, e.g. <code>Asia/Kolkata</code></td></tr><tr><td><code>days mon,tue,…</code></td><td>Which days the standup runs (default <code>mon–fri</code>)</td></tr><tr><td><code>questions</code></td><td>Show the current question list</td></tr><tr><td><code>questions set Q1 | Q2 | …</code></td><td>Replace the questions (1–10, pipe-separated)</td></tr><tr><td><code>questions reset</code></td><td>Back to the default three questions</td></tr><tr><td><code>mood on|off|anon</code> (also <code>anonymous</code>)</td><td>Mood dropdown; <code>anon</code> hides who felt what — the wrap-up shows the team average instead</td></tr><tr><td><code>escalate @user</code></td><td>DM this person when blockers stay open too long</td></tr><tr><td><code>escalate days N</code> / <code>escalate off</code></td><td>Escalation threshold (default 2 days) / disable</td></tr><tr><td><code>digest on|off</code></td><td>Weekly digest posted after the last run of the week</td></tr></tbody></table><h2 id="insights-everyone" tabindex="-1">Insights (everyone) <a class="header-anchor" href="#insights-everyone" aria-label="Permalink to &quot;Insights (everyone)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>status</code></td><td>Configuration + today&#39;s progress (submitted / pending / away)</td></tr><tr><td><code>trends</code></td><td>Last 4 weeks: participation % and average mood</td></tr><tr><td><code>blockers</code></td><td>Open blockers with ids, age, who&#39;s tagged, and update counts</td></tr><tr><td><code>export</code></td><td>How to download a CSV of submissions</td></tr></tbody></table><h2 id="working-a-blocker-together-everyone" tabindex="-1">Working a blocker together (everyone) <a class="header-anchor" href="#working-a-blocker-together-everyone" aria-label="Permalink to &quot;Working a blocker together (everyone)&quot;">​</a></h2><p>Blockers get an id (<code>blockers</code> shows them). Tag teammates to pull them in:</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>blocker 12 tag @Asha @Rohit</code></td><td>Tagged people get an interactive DM card (✋ Acknowledge · 📝 Add update · ✅ Resolve)</td></tr><tr><td><code>blocker 12 update &lt;text&gt;</code></td><td>Post an update — DMed to the reporter and everyone tagged, and added to the blocker&#39;s thread in the space</td></tr><tr><td><code>blocker 12 resolve</code></td><td>Close it (reporter, tagged people, or admins)</td></tr></tbody></table><p>How collaboration changes the lifecycle:</p><ul><li><strong>Tagging makes it explicit-resolve.</strong> Untagged blockers still auto-resolve when the reporter&#39;s next standup is blocker-free; once a blocker is tagged or has updates, only an explicit resolve closes it — someone&#39;s clean standup can&#39;t silently end a conversation others are having.</li><li><strong>Acknowledge stops the nudges.</strong> Tagged people get one DM per day (at run close) until they hit ✋ Acknowledge; posting an update acknowledges implicitly. The reporter is notified of every ack.</li><li><strong>Everything is tracked.</strong> Updates and resolution land in a per-blocker thread in the team space, and open blockers keep appearing in wrap-ups, digests, and escalation pings until resolved.</li></ul><h2 id="polls-everyone" tabindex="-1">Polls (everyone) <a class="header-anchor" href="#polls-everyone" aria-label="Permalink to &quot;Polls (everyone)&quot;">​</a></h2><p>Quick team decisions without a meeting — a card in the space, one tap to vote:</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>poll Question? | Option A | Option B</code></td><td>Post a poll card (2–6 options). Votes update the card live; voting again changes your vote</td></tr><tr><td><code>polls</code></td><td>List open polls with vote counts</td></tr><tr><td><code>poll &lt;id&gt; results</code></td><td>Current tallies with voter names</td></tr><tr><td><code>poll &lt;id&gt; close</code></td><td>Close it and post final results (creator or admin)</td></tr></tbody></table><h2 id="dm-self-service" tabindex="-1">DM self-service <a class="header-anchor" href="#dm-self-service" aria-label="Permalink to &quot;DM self-service&quot;">​</a></h2><p>Anyone can DM the bot directly:</p><table tabindex="0"><thead><tr><th>Message</th><th>Effect</th></tr></thead><tbody><tr><td><code>vacation</code> (or <code>ooo</code>)</td><td>Pause prompts for yourself across all your standups</td></tr><tr><td><code>back</code></td><td>Resume prompts</td></tr><tr><td><code>timezone &lt;IANA&gt;</code></td><td>Get prompts at the standup&#39;s prompt time in <em>your</em> timezone (all your standups)</td></tr><tr><td><code>timezone reset</code></td><td>Follow each standup&#39;s timezone again (<code>timezone</code> alone shows the current setting)</td></tr></tbody></table><h2 id="behavior-notes" tabindex="-1">Behavior notes <a class="header-anchor" href="#behavior-notes" aria-label="Permalink to &quot;Behavior notes&quot;">​</a></h2><ul><li><strong>Editing:</strong> re-open <em>Fill standup</em> before the deadline to edit — the posted card updates in place and is marked <em>edited</em>.</li><li><strong>Skip today:</strong> the prompt card has a 🏖️ <em>Skip today</em> button; skipped people are listed as away, not missing.</li><li><strong>Pre-fill:</strong> the &quot;yesterday&quot; answer is pre-filled from your previous &quot;today&quot; answer.</li><li><strong>Late submissions</strong> after the deadline still post, flagged <em>late</em>; the wrap-up isn&#39;t recalculated and late entries can no longer be edited.</li><li><strong>Untagged blockers</strong> auto-resolve when the same person submits a blocker-free standup on a later day; tagged ones need an explicit <code>blocker &lt;id&gt; resolve</code>. With <code>escalate @user</code> configured, the contact gets one DM at run close listing every blocker that newly crossed the threshold — each blocker is escalated once.</li><li><strong>Calendar OOO</strong> (when <a href="./configuration.html">enabled</a>): participants with an <em>Out of office</em> event in Google Calendar are automatically marked away for that day&#39;s run. Emails come from the Directory API when a Workspace admin email is configured (works for everyone immediately), otherwise they are learned from Chat interactions — kicking in after a person has used the bot at least once.</li><li><strong>Roster snapshots:</strong> the day&#39;s roster is frozen when the run opens; <code>add</code>/<code>remove</code>/<code>vacation</code> apply from the next run.</li><li><strong>Custom questions</strong> apply from the next run. Questions containing the word &quot;blocker&quot; get blocker tracking; questions containing &quot;yesterday&quot;/&quot;today&quot; get pre-fill behavior.</li></ul>',21)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
